　　绘制鼠标悬浮外边框核心源码如下：

  // 核心绘制方法：在行绘制完成后，额外绘制一个矩形边框
  private void DataGridView1_RowPostPaint(object sender, DataGridViewRowPostPaintEventArgs e)
  {
      // 第一行永远显示边框（最新记录）
      bool isFirstRow = (e.RowIndex == 0);
      // 当前行被选中时显示边框
      bool isSelected = dataGridView1.Rows[e.RowIndex].Selected;
      // 鼠标悬浮的行显示边框
      bool isHover = (_hoverRowIndex == e.RowIndex);

      // 只要满足任一条件即绘制
      if (!isFirstRow && !isSelected && !isHover)
          return;
      if (!dataGridView1.Rows[e.RowIndex].Visible)
          return;

      Rectangle rect = e.RowBounds;
      rect.X += 1;
      rect.Width -= 2;
      rect.Y += 1;
      rect.Height -= 2;

      using (Pen pen = new Pen(Color.FromArgb(0, 160, 230), 2.5f))
      {
          e.Graphics.DrawRectangle(pen, rect);
      }
  }



